"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, useEffect, useState } from "react";

import { cn } from "@/lib/utils";

/** Props for a thinking indicator. */
export type ThinkingIndicatorProps = Omit<ComponentPropsWithoutRef<"div">, "children"> & {
  /** What the assistant is doing now. Name the real step: "Reading 4 sources", not an invented one. */
  label?: string;
  /** Milliseconds to wait before anything shows, so a fast answer never flashes an indicator. */
  delay?: number;
};

const DOTS = [0, 1, 2];
// Seconds between one dot's swell and the next.
const STAGGER = 0.16;
// A there-and-back, so it eases both ways.
const SWELL: Transition = { duration: 1.2, ease: "easeInOut", repeat: Infinity };
// The band crosses at a constant speed; easing would make the loop pulse at its seam.
const SHIMMER: Transition = { duration: 1.8, ease: "linear", repeat: Infinity };
const SWAP: Transition = { duration: 0.2, ease: [0.165, 0.84, 0.44, 1] };
const FADE: Transition = { duration: 0.15 };

/**
 * Shows that the assistant is working before any text arrives: three dots that
 * swell in turn, beside a label whose text shimmers. Change the label as the
 * work moves on and the new one fades in and is announced.
 */
export function ThinkingIndicator({ label = "Thinking", delay = 300, className, ...divProps }: ThinkingIndicatorProps) {
  const [shown, setShown] = useState(delay <= 0);
  const reduceMotion = useReducedMotion();

  useEffect(() => {
    if (shown) return;
    const timer = window.setTimeout(() => setShown(true), delay);
    return () => window.clearTimeout(timer);
  }, [delay, shown]);

  return (
    // The status region exists from the start, so the label is announced when it appears.
    <div {...divProps} role="status" className={cn("inline-flex min-h-6 items-center gap-2 text-sm", className)}>
      {shown && (
        <>
          <motion.span
            aria-hidden="true"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={FADE}
            // The gap is a full dot wide, so two swollen neighbours never touch.
            className="flex items-center gap-1.5"
          >
            {DOTS.map((dot) => (
              <motion.span
                key={dot}
                animate={reduceMotion ? { scale: 1, opacity: 0.7 } : { scale: [1, 1.3, 1], opacity: [0.4, 1, 0.4] }}
                transition={reduceMotion ? FADE : { ...SWELL, delay: dot * STAGGER }}
                className="size-1.5 rounded-full bg-muted-foreground"
              />
            ))}
          </motion.span>
          <motion.span
            // A new label is a new element, so it fades in instead of changing under the eye.
            key={label}
            initial={reduceMotion ? { opacity: 0 } : { opacity: 0, y: 4, backgroundPositionX: "100%" }}
            animate={reduceMotion ? { opacity: 1 } : { opacity: 1, y: 0, backgroundPositionX: "-100%" }}
            transition={reduceMotion ? FADE : { opacity: SWAP, y: SWAP, backgroundPositionX: SHIMMER }}
            className={cn(
              "font-medium",
              reduceMotion
                ? "text-muted-foreground"
                : // The text is clipped out of a gradient twice its width; sliding the gradient moves the bright band.
                  "bg-linear-to-r from-muted-foreground from-40% via-foreground via-50% to-muted-foreground to-60% bg-size-[200%_100%] bg-clip-text text-transparent",
            )}
          >
            {label}
          </motion.span>
        </>
      )}
    </div>
  );
}
